import { describe, expect, it } from 'vitest';
import { Add, I, Mul, Pow, S, Sum, Sym, add, differenceDelta, dominant, fn, limitSeq, log, mul, oo, pi, pow, rational, symbols, together } from '../../src';
import { sympyStr } from '../sympy-str';

describe("doctests of sympy.series.limitseq", () => {
  it("limit_seq((5*n**3 + 3*n**2 + 4) / (3*n**3 + 4*n - 5), n)", () => {
    const n = new Sym('n');
    expect(sympyStr(limitSeq(mul(pow(add(-5, mul(3, pow(n, 3)), mul(4, n)), -1), add(4, mul(3, pow(n, 2)), mul(5, pow(n, 3)))), n))).toBe('5/3');
  });
  it("limit_seq(binomial(2*n, n) / Sum(binomial(2*k, k), (k, 1, n)), n)", () => {
    const [k, n] = symbols('k n');
    expect(sympyStr(limitSeq(mul(pow(Sum(fn('binomial', [mul(2, k), k]), [k, rational(1), n]), -1), fn('binomial', [mul(2, n), n])), n))).toBe('3/4');
  });
  it("limit_seq(Sum(k**2 * Sum(2**m/m, (m, 1, k)), (k, 1, n)) / (2**n*n), n)", () => {
    const [n, k, m] = symbols('n k m');
    expect(sympyStr(limitSeq(mul(pow(2, mul(-1, n)), pow(n, -1), Sum(mul(pow(k, 2), Sum(mul(pow(2, m), pow(m, -1)), [m, rational(1), k])), [k, rational(1), n])), n))).toBe('4');
  });
  it("dominant(5*n**3 + 4*n**2 + n + 1, n)", () => {
    const n = new Sym('n');
    expect(sympyStr(dominant(add(1, n, mul(4, pow(n, 2)), mul(5, pow(n, 3))), n))).toBe('5*n**3');
  });
  it("dominant(2**n + Sum(k, (k, 0, n)), n)", () => {
    const [n, k] = symbols('n k');
    expect(sympyStr(dominant(add(pow(2, n), Sum(k, [k, rational(0), n])), n))).toBe('2**n');
  });
});

